import { useEffect, useState } from 'react';
import axios from '../../api/axiosInstance';
import { useNavigate } from 'react-router-dom';

const Projects = () => {
    const [projects, setProjects] = useState([]);
    const [search, setSearch] = useState('');
    const navigate = useNavigate();

    const fetchProjects = async () => {
        const res = await axios.get('/projects');
        setProjects(res.data);
    };

    useEffect(() => { fetchProjects(); }, []);

    const handleDelete = async (id) => {
        if (window.confirm('Bạn có chắc muốn xóa dự án này?')) {
            await axios.delete(`/projects/${id}`);
            fetchProjects();
        }
    };

    const handleEdit = (project) => {
        navigate('/admin/projects/add', { state: { editData: project } });
    };

    return (
        <div>
            <h2>📁 Danh sách Dự án</h2>

            <input
                type="text"
                placeholder="Tìm kiếm dự án..."
                onChange={(e) => setSearch(e.target.value)}
                style={{ marginBottom: '10px', padding: '8px', width: '300px' }}
            />

            <table border="1" cellPadding="10" width="100%">
                <thead>
                    <tr>
                        <th>Hình ảnh</th>
                        <th>Tên</th>
                        <th>Tiến độ (%)</th>
                        <th>Ngân sách</th>
                        <th>Bắt đầu</th>
                        <th>Kết thúc</th>
                        <th>Hành động</th>
                    </tr>
                </thead>
                <tbody>
                    {projects.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                        <tr key={p._id}>
                            <td><img src={p.image} alt="" width="60" /></td>
                            <td>{p.name}</td>
                            <td>{p.progress}%</td>
                            <td>{p.budget?.toLocaleString()}đ</td>
                            <td>{p.startDate?.slice(0, 10)}</td>
                            <td>{p.endDate?.slice(0, 10)}</td>
                            <td>
                                <button onClick={() => handleEdit(p)} style={{ marginRight: 10 }}>✏️</button>
                                <button onClick={() => handleDelete(p._id)}>🗑️</button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <button onClick={() => navigate('/admin/projects/add')} style={{ marginTop: 20 }}>➕ Thêm Dự Án</button>
        </div>
    );
};

export default Projects;
